from __future__ import annotations

import sys

sys.dont_write_bytecode = True

import argparse  # noqa: E402
import hashlib  # noqa: E402
import json  # noqa: E402
import math  # noqa: E402
import time  # noqa: E402
from pathlib import Path  # noqa: E402

import numpy as np  # noqa: E402

HERE = Path(__file__).resolve().parent
R0 = 0.4749
RATIO_SHARED, RATIO_INDEP = 3.0, 1.5
LAGS = 80
QUOTED_SCATTER = {"Y": [0.22, 0.19, 0.32], "X": [0.75, 1.17, 0.95], "note": "as t13-rule.md quotes test 12's recount"}
MONITOR = [("t11", 2), ("t11", 3), ("t12", 1)]


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def wrap(x):
    y = (x + math.pi) % (2 * math.pi) - math.pi
    return math.pi if y == -math.pi else y


def circ_mean(th):
    return float(np.angle(np.mean(np.exp(1j * np.asarray(th)))))


def median_one_sheet(th):
    ref = circ_mean(th)
    return wrap(ref + float(np.median([wrap(t - ref) for t in th])))


def ones_of(cts):
    return sum(v for k, v in cts.items() if k[-1] == "1")


def check_hashes(d):
    rec = {}
    for line in (d / "shots-t13-hashes-before-analysis.txt").read_text().splitlines():
        parts = line.split()
        if len(parts) == 2 and len(parts[0]) == 64:
            rec[parts[1]] = parts[0]
    out = {f: {"recorded": h, "now": sha(d / f), "equal": sha(d / f) == h} for f, h in rec.items()}
    return out, all(v["equal"] for v in out.values()) and bool(out)


def readings(bits, n_shots, sweep_s):
    """(a), (b) and (c)'s scatter on one bit matrix, as Mantri's desk check computes them."""
    n = bits.shape[0]
    p = bits.mean(axis=1)
    pbar = float(p.mean())
    mj = bits.mean(axis=0)
    v_obs = float(mj.var(ddof=1))
    v_ind = float((p * (1 - p)).mean() / n)
    ratio = v_obs / v_ind if v_ind > 0 else math.inf
    word = "SHARED" if ratio > RATIO_SHARED else ("INDEPENDENT" if ratio < RATIO_INDEP else "UNDECIDED")
    x = mj - mj.mean()
    v0 = float(np.sum(x * x))
    acf = [float(np.sum(x[l:] * x[:-l]) / v0) if v0 > 0 else 0.0 for l in range(1, LAGS + 1)]
    excess = 1 - v_ind / v_obs if v_obs > 0 else 0.0
    below = [i for i, a in enumerate(acf) if a < excess / math.e]
    lag_e = below[0] + 1 if below else LAGS + 1
    read = word == "SHARED" and lag_e >= 3
    xr = bits - p[:, None]
    ac1 = [float(np.sum(r[1:] * r[:-1]) / np.sum(r * r)) if np.sum(r * r) > 0 else 0.0 for r in xr]
    scat = float(p.var(ddof=1) / (pbar * (1 - pbar) / n_shots)) if 0 < pbar < 1 else None
    return {"n_rows": n, "n_shots": n_shots, "ratio": ratio, "v_obs": v_obs, "v_ind": v_ind, "word": word,
            "acf_lags_1_to_80": acf, "excess_over_independent": excess, "threshold": excess / math.e, "lag_1_over_e": lag_e,
            "lag_found_within_80": bool(below), "sweep_s": sweep_s, "correlation_time_read": read,
            "correlation_time_sweeps": lag_e if read else None, "correlation_time_s": lag_e * sweep_s if read else None,
            "correlation_time_word": None if read else "under three sweeps",
            "row_lag1_autocorrelation_mean": float(np.mean(ac1)), "row_lag1_se": 1 / math.sqrt(n * n_shots),
            "scatter_ratio_from_arrays": scat, "pbar": pbar, "p_rows": [float(v) for v in p]}


def load_job(d, counts_path, test, n):
    rec = json.loads(Path(counts_path).read_text())
    arr = np.load(d / f"shots-t13-{test}-job{n}.npz")
    meta = json.loads((d / f"shots-t13-{test}-job{n}-meta.json").read_text())
    keys = sorted(arr.files)
    mism = []
    for i, (cts, shots) in enumerate(zip(rec["counts"], rec["shots"])):
        a = arr[f"p{i:03d}"]
        o_pub, z_pub = ones_of(cts), shots - ones_of(cts)
        o, z = int(a.sum()), int(len(a) - a.sum())
        if (o, z) != (o_pub, z_pub) or len(a) != shots:
            mism.append({"position": i, "array": [o, z], "published": [o_pub, z_pub]})
    check = {"positions": len(rec["counts"]), "arrays": len(keys), "mismatches": mism, "pass": not mism and len(keys) == len(rec["counts"]),
             "counts_file": Path(counts_path).name, "counts_file_sha256": sha(counts_path)}
    return rec, arr, meta, check


def spans_of(rec):
    sp = (rec.get("execution_metadata") or {}).get("execution_spans") or []
    return sorted(sp, key=lambda s: s["start_utc"])


def read_monitor(d, counts_path, test, n, weights):
    rec, arr, meta, check = load_job(d, counts_path, test, n)
    out = {"test": test, "job": n, "job_id": rec["job_id"], "fetched_utc": meta["fetched_utc"], "per_shot_data_available": meta["per_shot_data_available"],
           "counts_check": check}
    if not check["pass"]:
        out["note"] = "the counts check failed; the read of this job stops here"
        return out
    labels, shots = rec["labels"], rec["shots"]
    N = shots[0]
    P = [ones_of(c) / s for c, s in zip(rec["counts"], shots)]
    ro = [i for i, l in enumerate(labels) if l["circuit"] in ("P10", "P01")]
    c = float(np.mean([P[i] for i in ro]))
    xpos = {l["repeat"]: i for i, l in enumerate(labels) if l["circuit"] == "X"}
    ypos = {l["repeat"]: i for i, l in enumerate(labels) if l["circuit"] == "Y"}
    reps = sorted(xpos)
    theta = {k: math.atan2(P[ypos[k]] - c, P[xpos[k]] - c) for k in reps}
    med = median_one_sheet([theta[k] for k in reps])
    qrec = "Y" if abs(math.sin(med)) > abs(math.cos(med)) else "X"
    spans = spans_of(rec)
    span_of = {p: s["span"] for s in spans for p in s["positions"]}
    whole = {s["span"]: [k for k in reps if span_of.get(xpos[k]) == s["span"] == span_of.get(ypos[k])] for s in spans}
    straddle = [k for k in reps if span_of.get(xpos[k]) != span_of.get(ypos[k])]
    out.update({"c": c, "median_phase": med, "quadrature_of_record": qrec, "straddling_repeats": straddle, "spans": []})
    words = []
    for si, s in enumerate(spans):
        ks = whole[s["span"]]
        if len(ks) < 2:
            out["spans"].append({"span": s["span"], "n_whole_repeats": len(ks), "note": "fewer than two whole repeats; not read"})
            continue
        sweep = s["duration_s"] / N
        row = {"span": s["span"], "n_whole_repeats": len(ks), "first_last_repeat": [ks[0], ks[-1]], "duration_s": s["duration_s"], "sweep_s": sweep}
        tb = circ_mean([theta[k] for k in ks])
        b = weights[si] if si < len(weights) else None
        for q, pos, g in (("Y", ypos, math.sin), ("X", xpos, math.cos)):
            M = np.stack([arr[f"p{pos[k]:03d}"] for k in ks]).astype(float)
            r = readings(M, N, sweep)
            pc = np.array([P[pos[k]] for k in ks])
            pb = float(pc.mean())
            r["scatter_ratio_from_counts"] = float(pc.var(ddof=1) / (pb * (1 - pb) / N))
            pl, pu = c + R0 * g(tb), c - R0 * g(tb)
            r["shared_state_residual_prediction"] = ((b * pu * (1 - pu) + (1 - b) * pl * (1 - pl)) / (r["pbar"] * (1 - r["pbar"]))) if b is not None else None
            r["lines_for_the_prediction"] = {"p_l": pl, "p_u": pu, "b": b, "theta_bar": tb}
            if q != qrec:
                r["word"] = None    # the other quadrature: numbers beside, without words
            row[q] = r
        words.append(row[qrec]["word"])
        out["spans"].append(row)
    out["job_word"] = ("SHARED" if words and all(w == "SHARED" for w in words) else ("INDEPENDENT" if words and all(w == "INDEPENDENT" for w in words) else "MIXED"))
    out["span_words"] = words
    for q, pos in (("Y", ypos), ("X", xpos)):
        pc = np.array([P[pos[k]] for k in reps])
        pb = float(pc.mean())
        out[f"whole_job_scatter_ratio_from_counts_{q}"] = float(pc.var(ddof=1) / (pb * (1 - pb) / N))
    return out


def read_job1(d, counts_path):
    rec, arr, meta, check = load_job(d, counts_path, "t11", 1)
    out = {"test": "t11", "job": 1, "job_id": rec["job_id"], "fetched_utc": meta["fetched_utc"], "per_shot_data_available": meta["per_shot_data_available"],
           "counts_check": check, "note": "beside, without verdict words (the author's ruling): per span, (a)'s ratio and the per-row lag 1 autocorrelation on the Y positions and separately on the X positions, rows in submitted order, readout left out"}
    if not check["pass"]:
        out["note2"] = "the counts check failed; the read of this job stops here"
        return out
    labels, N = rec["labels"], rec["shots"][0]
    spans = spans_of(rec)
    out["spans"] = []
    for s in spans:
        row = {"span": s["span"], "duration_s": s["duration_s"]}
        for q in ("Y", "X"):
            pos = [p for p in sorted(s["positions"]) if labels[p]["circuit"] == q]
            if len(pos) < 2:
                row[q] = {"n_rows": len(pos), "note": "fewer than two positions"}
                continue
            M = np.stack([arr[f"p{p:03d}"] for p in pos]).astype(float)
            r = readings(M, N, s["duration_s"] / N)
            row[q] = {k: r[k] for k in ("n_rows", "ratio", "v_obs", "v_ind", "row_lag1_autocorrelation_mean", "row_lag1_se")}
            row[q]["positions"] = pos
        out["spans"].append(row)
    return out




